for tier,items in groups:
    for source,id,name,kit in items:
        role,rng,dmg,interval=roles[kit];i=len(rows)
        cost=100 if id=='prism-sentry' else 140 if id=='longwatch' else 100+(i%5)*20
        price=250 if id=='longwatch' else 120+i*15
        rows.append(dict(id=id,name=name,sourceRole=source,tier=tier,kit=kit,role=role,range=rng,damage=dmg,intervalSeconds=interval,cost=cost,unlockPrice=price,currency='shards' if tier=='Hardcore' else 'coins',color=colors[i%7],appearance=i,description=f'{name} is a human {role.lower()} specialist. '+{'splash':'Hits enemies within 2.5 m of the target.','slow':'Slows normal enemies by 45%; bosses resist control.','freeze':'Briefly stops normal enemies; bosses resist control.','economy':'Produces 12 battle cash every 5 seconds during combat.','heal':'Restores 1 base health every 5 seconds, up to 10.','support':'Nearby allies attack 25% faster; auras do not stack.','summon':'Sends a friendly runner down the road every 3 seconds.','chain':'Strikes up to three nearby enemies.','bounty':'Earns 2 battle cash per hit.','burn':'Applies damage over time.','poison':'Applies damage over time.','bleed':'Applies damage over time.','pierce':'Strikes up to three nearby enemies.','spread':'Hits up to three enemies near the target.'}.get(kit,'Automatically attacks the furthest enemy in range.')))
# Golden counterparts stay characters and use the same working kits.
for source in ['Scout','Demoman','Soldier','Pyromancer','Crook Boss','Cowboy','Snowballer']:
    base=next(r for r in rows if r['sourceRole']==source);r={**base,'id':'gilded-'+base['id'],'name':'Gilded '+base['name'],'sourceRole':'Golden '+source,'tier':'Golden','cost':base['cost']+50,'damage':round(base['damage']*1.5),'unlockPrice':2500,'color':0xffd166};rows.append(r)
