# Original vector portraits and symbols are UI artwork, never world sprites.
def svg(body):return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128">'+body+'</svg>'
for r in rows:
    c=f'#{r["color"]:06x}';i=r['appearance'];skin=['#bd886b','#e4b591','#825843','#b77755'][i%4]
    body=f'<rect width="128" height="128" rx="20" fill="#142734"/><circle cx="64" cy="57" r="47" fill="{c}" opacity=".15"/><path d="M17 128V94Q23 77 47 76H81Q106 77 111 94V128" fill="{c}"/><path d="M47 79L64 102 81 79V128H47Z" fill="#294553"/><path d="M43 35H85V66Q82 83 64 84 44 80 43 66Z" fill="{skin}"/><path d="M38 40V29Q64 9 90 29V40Z" fill="{c}"/><path d="M40 40H88V48H40Z" fill="#253b49"/><path d="M48 53H57M71 53H80" stroke="#172730" stroke-width="5"/><path d="M59 68H72" stroke="#754d43" stroke-width="3"/>'
    if r['kit'] in ['melee','bleed']:body+='<path d="M93 110L106 44 113 29 117 49 105 113Z" fill="#e1edf0"/><path d="M89 100L116 106" stroke="#e4b965" stroke-width="7"/>'
